package com.lifeos.events; import com.lifeos.shared.AuditableEntity; import com.lifeos.users.User; import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="events") public class Event extends AuditableEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=200) private String title; @Column(columnDefinition="text") private String description; @Column(nullable=false) private LocalDateTime startDateTime; @Column(nullable=false) private LocalDateTime endDateTime; @Column(length=300) private String location; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) private User user; public Long getId(){return id;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public LocalDateTime getStartDateTime(){return startDateTime;} public void setStartDateTime(LocalDateTime v){startDateTime=v;} public LocalDateTime getEndDateTime(){return endDateTime;} public void setEndDateTime(LocalDateTime v){endDateTime=v;} public String getLocation(){return location;} public void setLocation(String v){location=v;} public User getUser(){return user;} public void setUser(User v){user=v;} }
